import java.io.*;
import java.util.*;

public class Main {
    private static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    private static PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) {
        try {
            long n = nextInt64();
            long sum = 0;
            long i = 0;

            while (sum + i + 1 <= n) {
                sum += i;
                i++;
            }

            println(n - sum);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
        }
    }

    private static String next() throws IOException {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (!line.isEmpty()) {
                return line;
            }
        }
        throw new IOException("No more input");
    }

    private static long nextInt64() throws IOException {
        return Long.parseLong(next());
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private static double nextFloat() throws IOException {
        return Double.parseDouble(next());
    }

    private static void println(Object... args) {
        writer.println(Arrays.toString(args).replace("[", "").replace("]", "").replace(",", ""));
    }

    private static void print(Object... args) {
        writer.print(Arrays.toString(args).replace("[", "").replace("]", "").replace(",", ""));
    }

    private static void printf(String format, Object... args) {
        writer.printf(format, args);
