import java.io.*;
import java.util.*;

public class Main {
    private static final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    private static final BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));

    public static void main(String[] args) throws IOException {
        try {
            long n = nextInt64();
            long sum = 0;
            long i = 0;

            while (sum + i + 1 <= n) {
                sum += i;
                i++;
            }

            println(n - sum);
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static String next() throws IOException {
        String line = reader.readLine();
        if (line == null) {
            throw new IOException("No more input");
        }
        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) {
            throw new IOException("No more tokens");
        }
        return st.nextToken();
    }

    private static long nextInt64() throws IOException {
        return Long.parseLong(next());
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private static double nextFloat() throws IOException {
        return Double.parseDouble(next());
    }

    private static void println(Object... a) throws IOException {
        for (int i = 0; i < a.length; i++) {
            if (i > 0) writer.write(' ');
            writer.write(String.valueOf(a[i]));
        }
        writer.newLine();
    }

    private static void print(Object... a) throws IOException {
        for (Object obj : a) {
            writer.write(String.valueOf(obj));
        }
    }

    private static void printf(String format, Object... a) throws IOException {
        writer.write(String.format(format, a));
    }
}
